def add_days_to_date(y, m, d, n):
    day = d + n
    month = m
    year = y
    while day > 31:
        day -= 31
        month += 1
        if month > 12:
            month = 1
            year += 1
    while day < 1:
        month -= 1
        if month < 1:
            month = 12
            year -= 1
        day += 31
    return (year, month, day)

