def is_valid_sudoku_diagonal(board):
    if len(board) != 9 or any(len(row) != 9 for row in board):
        return False
    diag = [board[i][i] for i in range(9)]
    if any(not isinstance(v, int) or v < 0 or v > 9 for v in diag):
        return False
    nonzero = [v for v in diag if v != 0]
    return len(nonzero) == len(set(nonzero))

