def reverse_digits_in_string(s):
    from collections import deque
    stack = deque(ch for ch in s if ch.isdigit())
    result = []
    for ch in s:
        if ch.isdigit():
            result.append(stack.pop())
        else:
            result.append(ch)
    return ''.join(result)

def reindent(text, old_n, new_n):
    lines = text.split('\n')
    result_lines = []
    for line in lines:
        leading = 0
        while leading < len(line) and line[leading] == ' ' and leading < old_n:
            leading += 1
        if leading == old_n:
            result_lines.append(' ' * new_n + line[old_n:])
        else:
            result_lines.append(line)
    return '\n'.join(result_lines)

